import { spawn } from "node:child_process";
import { stripVTControlCharacters } from "node:util";

/** Redact known secrets (including transformed values) and credentials generated by local tooling. */
export function redact(text, env = process.env) {
  let output = stripVTControlCharacters(text);
  const secrets = new Set();
  for (const [name, value] of Object.entries(env)) {
    if (!value || !/PASSWORD|SECRET|TOKEN|API_KEY|DATABASE_URL|DB_URL|PUBLISHABLE_KEY|ANON_KEY/i.test(name))
      continue;
    const values = [value];
    if (/DATABASE_URL|DB_URL/.test(name)) {
      try {
        const password = new URL(value.trim()).password;
        values.push(password, decodeURIComponent(password));
      } catch {
        /* Invalid input is never echoed by the diagnostics. */
      }
    }
    for (const secret of values
      .flatMap((value) => [value, ...value.split(/[\r\n]/)])
      .filter((value) => value.length >= 4)) {
      for (const form of [
        secret,
        encodeURIComponent(secret),
        Buffer.from(secret).toString("base64"),
        JSON.stringify(secret).slice(1, -1),
      ]) {
        secrets.add(form);
      }
    }
  }
  for (const secret of [...secrets].sort((a, b) => b.length - a.length)) {
    output = output.replaceAll(secret, "[REDACTED]");
  }
  return output
    .replace(/\b(?:sb_secret_|sb_publishable_|rnd_|gh[pousr]_)[A-Za-z0-9_-]+/g, "[REDACTED_KEY]")
    .replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, "[REDACTED_JWT]")
    .replace(/\b(?:postgres(?:ql)?|redis|mongodb(?:\+srv)?):\/\/[^\s"'<>]+/gi, "[REDACTED_DATABASE_URL]")
    .replace(/\bBearer\s+[^\s"'<>]+/gi, "Bearer [REDACTED]")
    .replace(
      /((?:jwt[_ ]?secret|service[_ ]?role[_ ]?key|secret[_ ]?key|password)\s*[":=│]+\s*)[^\r\n│]+/gi,
      "$1[REDACTED]",
    );
}

/** Buffer through newlines so a credential split across stream chunks cannot escape redaction. */
export async function runCli(command, args, { env = process.env, cwd, stdin = "inherit" } = {}) {
  const child = spawn(command, args, {
    cwd,
    env,
    stdio: [stdin, "pipe", "pipe"],
    shell: process.platform === "win32",
  });
  let stdout = "";
  for (const [stream, destination, capture] of [
    [child.stdout, process.stdout, true],
    [child.stderr, process.stderr, false],
  ]) {
    let pending = "";
    stream.setEncoding("utf8");
    const emit = (line) => {
      const safe = redact(line, env);
      if (capture) stdout += safe;
      destination.write(safe);
    };
    stream.on("data", (chunk) => {
      pending += chunk;
      let end = pending.indexOf("\n");
      while (end >= 0) {
        emit(pending.slice(0, end + 1));
        pending = pending.slice(end + 1);
        end = pending.indexOf("\n");
      }
    });
    stream.on("end", () => {
      if (pending) emit(pending);
    });
  }
  const status = await new Promise((resolve) => {
    child.on("error", () => {
      console.error("Could not start subprocess.");
      resolve(1);
    });
    child.on("close", (code) => resolve(code ?? 1));
  });
  return { status, stdout };
}
